<?php session_start();require_once __DIR__.'/config/database.php';$code=strtoupper(trim($_GET['code']??''));$s=$pdo->prepare('SELECT * FROM orders WHERE tracking_code=?');$s->execute([$code]);$o=$s->fetch();$steps=['Order Placed','Packed','Shipped','Out for Delivery','Delivered'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track order</title><link rel="stylesheet" href="css/style.css"></head><body><main class="page-wrap"><h1>Track your order</h1><form method="get"><input name="code" placeholder="Enter tracking ID" required value="<?= htmlspecialchars($code) ?>"><button class="btn">Track</button></form><?php if($code&&!$o): ?><p>Tracking ID not found.</p><?php endif; ?><?php if($o): ?><h2><?= htmlspecialchars($o['tracking_code']) ?> — <?= htmlspecialchars($o['status']) ?></h2><ol><?php foreach($steps as $step): ?><li><?= htmlspecialchars($step) ?> <?= array_search($step,$steps)<=array_search($o['status'],$steps)?'✓':'(pending)' ?></li><?php endforeach; ?></ol><p>Total: ₹<?= number_format($o['total'],2) ?></p><small>This is a simulated status timeline, not live GPS/courier tracking.</small><?php endif; ?><p><a href="index.php">Back to shop</a></p></main></body></html>